/* InstiQuote interactive prototype. All mutations are browser-local. */
(() => {
  'use strict';
  const $ = (s, el = document) => el.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
    list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',
    plus:'M12 5v14 M5 12h14', bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
    search:'M21 21l-4.5-4.5 M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',
    book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v16',
    file:'M14 2H5v20h14V7z M14 2v6h5 M8 13h8 M8 17h5',
    check:'M5 12l4 4L19 6', clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',
    people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
    help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    calendar:'M8 2v4 M16 2v4 M3 10h18 M3 4h18v18H3z',
    upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',
    close:'M6 6l12 12 M6 18 18 6',chevron:'M9 5l7 7-7 7',
    mail:'M3 5h18v14H3z M3 5l9 8 9-8', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',
    spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',
    download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5', rotate:'M3 10a9 9 0 1 1 2 8 M3 3v7h7',money:'M3 5h18v14H3z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    activity:'M3 12h4l3-8 4 16 3-8h4',building:'M5 22V3h14v19 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M9 15h1 M14 15h1 M10 22v-3h4v3',
    message:'M21 3H3v14h5v4l5-4h8z M7 8h10 M7 12h6'
  };
  const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
  const money = n => `HK$ ${Number(n||0).toLocaleString('en-HK')}`;
  const date = (d, time=false) => new Date(d).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong',month:'2-digit',day:'2-digit',...(time?{hour:'2-digit',minute:'2-digit',hour12:false}:{})});
  const left = d => {const h=Math.ceil((new Date(d)-Date.now())/3600000);return h<=0?'已截止':h>=24?`${Math.floor(h/24)}天 ${h%24}小時`:`${h}小時`;};
  let state = window.IQ.load();
  window.IQ.ensureWorkflow(state);
  window.IQAccess.ensure(state);
  let ui={role:'teacher',view:'dashboard',requestId:null,filter:'all',search:'',step:1,supplierId:'sup-1',notifications:false};
  const entryParams=new URLSearchParams(window.location.search);
  const entryRole=entryParams.get('role');
  if(['teacher','supplier','admin','superadmin'].includes(entryRole)){ui.role=entryRole;ui.view=entryRole==='superadmin'?'system':'dashboard';}
  const entryViews={teacher:['dashboard','requests','new','guide'],supplier:['dashboard','quotes','profile','guide'],admin:['dashboard','requests','suppliers','whatsapp','accounts','logs','guide'],superadmin:['system','accounts','admins','permissions','access-audit','requests','suppliers','whatsapp','logs','guide']};
  if(entryViews[ui.role].includes(entryParams.get('view')))ui.view=entryParams.get('view');
  let draft={title:'',category:'到校課程',district:'九龍城區',description:'',budget:'',deadlineHours:72,school:'',teacher:'',phone:'',email:'',files:[],verified:false};
  try{draft={...draft,...JSON.parse(localStorage.getItem('instiquote-draft')||'{}')};}catch{}
  if(window.IQLocale) draft=window.IQLocale.migrateDraft(draft);
  let toastTimer;
  const toast = msg => {const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);};
  const safe = action => {try{action();}catch(e){toast(e.message||'操作未完成，請再試一次。');}};
  const btn=(label,action,kind='secondary',ico='',extra='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
  const supplier = id => state.suppliers.find(s=>s.id===id);
  const request = () => state.requests.find(r=>r.id===ui.requestId);
  const roleName = {teacher:'老師工作台',supplier:'供應商工作台',admin:'管理員工作台',superadmin:'總後台'};
  const categoryIcon = c=>({'到校課程':'book','到校活動':'spark','印刷製作':'file','小型維修':'settings'}[c]||'book');
  const statuses={matching:['匹配供應商','blue'],collecting:['分階段收集中','amber'],ready:['有效報價已備妥','green'],selected:['已加入洽談名單','blue'],closed:['收集已結束','gray'],cancelled:['已取消','red']};
  const badge=r=>`<span class="badge ${statuses[r.status]?.[1]||'gray'}">${statuses[r.status]?.[0]||r.status}</span>`;
  const anonymize=(v,r)=>{let s=String(v||'');[r.school,r.teacher,r.phone,r.email].filter(Boolean).forEach(x=>s=s.split(x).join('［已隱藏］'));return s;};
  const suppliersFor=r=>state.suppliers.filter(s=>r.invitations.some(i=>i.supplierId===s.id));
  const countAccepted=r=>r.invitations.filter(i=>i.status==='accepted').length;
  const waView=window.IQWhatsAppView.create({getState:()=>state,getRole:()=>isStaff()?'admin':ui.role,canPermission:can,esc,icon,btn,heading,stats,date,toast,modal,closeModal,render});
  const accountView=window.IQAccessView.create({getState:()=>state,getActorId:()=>actor()?.id,getRole:()=>ui.role,esc,icon,btn,heading,stats,date,toast,modal,closeModal,render,navigate});
  let session={accounts:{},revisions:{},signedOut:false};
  try{session={...session,...JSON.parse(sessionStorage.getItem('instiquote-demo-session')||'{}')};}catch{}
  function saveSession(){try{sessionStorage.setItem('instiquote-demo-session',JSON.stringify(session));}catch{}}
  function bindRequestOwners(){
    let changed=false;
    state.requests.forEach(r=>{if(!r.ownerAccountId){const owner=state.access.accounts.find(a=>a.type==='teacher'&&a.email.toLowerCase()===String(r.email).toLowerCase());r.ownerAccountId=owner?.id||'legacy-unassigned';changed=true;}});
    if(changed)window.IQ.save(state);
  }
  function syncExternalState(){const before=JSON.stringify(state);state=window.IQ.load();window.IQ.ensureWorkflow(state);window.IQAccess.ensure(state);bindRequestOwners();if(window.IQWhatsApp.syncWorkflow)window.IQWhatsApp.syncWorkflow(state);return JSON.stringify(state)!==before;}
  function initializeSession(){
    window.IQAccess.ensure(state);bindRequestOwners();
    ['teacher','supplier','admin','superadmin'].forEach(type=>{
      if(!state.access.accounts.some(a=>a.id===session.accounts[type]&&a.type===type))session.accounts[type]=state.access.accounts.find(a=>a.type===type)?.id;
      const a=state.access.accounts.find(a=>a.id===session.accounts[type]);
      if(a&&session.revisions[a.id]===undefined)session.revisions[a.id]=a.loginRevision;
    });
    const a=actor();
    if(a&&session.revisions[a.id]!==a.loginRevision)session.signedOut=true;
    if(ui.role==='supplier')ui.supplierId=a?.supplierId;
  }
  function actor(){return window.IQAccess.account(state,session.accounts[ui.role]);}
  function isStaff(){return ['admin','superadmin'].includes(ui.role);}
  function active(){const a=actor();return !!(a&&a.type===ui.role&&a.status==='active'&&!session.signedOut&&session.revisions[a.id]===a.loginRevision);}
  function can(permission){return active()&&window.IQAccess.can(state,actor().id,permission);}
  function requireActive(type){if(!active())throw Error('演示帳號已停用或登入已失效，請重新登入其他可用帳號。');if(type&&ui.role!==type)throw Error('請切換至對應的演示帳號操作。');return actor();}
  function requirePermission(permission){requireActive();window.IQAccess.requirePermission(state,actor().id,permission);}
  function ownRequest(r){const a=actor();return !!(r&&a&&ui.role==='teacher'&&r.ownerAccountId===a.id);}
  function visibleRequests(){return ui.role==='teacher'?state.requests.filter(ownRequest):state.requests;}
  function requireOwnRequest(r){requireActive('teacher');if(!ownRequest(r))throw Error('這份需求不屬於目前的老師帳號。');}
  function requireSupplier(){const a=requireActive('supplier');if(!a.supplierId||a.supplierId!==ui.supplierId)throw Error('此帳號未綁定有效供應商公司。');const s=supplier(a.supplierId);if(!s||s.status!=='approved')throw Error('供應商公司尚未通過審核或已停權。');return a;}
  function roleHome(){return ui.role==='superadmin'?'system':'dashboard';}
  function switchRole(role){if(!['teacher','supplier','admin','superadmin'].includes(role))throw Error('無效的演示角色。');ui.role=role;session.signedOut=false;initializeSession();const a=actor();if(a)session.revisions[a.id]=a.loginRevision;saveSession();closeModal();navigate(roleHome());}
  function sessionBar(){const a=actor(),accounts=state.access.accounts.filter(a=>a.type===ui.role);return `<section class="session-bar"><div class="session-identity"><label for="session-account" class="field-label">演示帳號</label><select id="session-account" class="select" aria-label="選擇演示帳號">${accounts.map(x=>`<option value="${x.id}" ${x.id===a?.id?'selected':''}>${esc(x.name)}${x.roleId?' · '+esc(window.IQAccess.roles(state).find(r=>r.id===x.roleId)?.name||''):''}${x.status==='disabled'?' · 已停用':''}</option>`).join('')}</select><span class="badge ${active()?'green':'amber'}">${active()?'使用中':a?.status==='disabled'?'已停用':'未登入'}</span></div><span class="session-caption">帳號與權限為本機演示，尚未接入正式登入服務。</span>${btn(active()?'登出演示':'登入演示帳號',active()?'session-signout':'session-signin','ghost small')}</section>`;}
  function denied(title='沒有存取權限',description='目前的演示帳號未獲授權使用這項功能。'){return `<section class="panel access-denied"><div class="panel-body">${icon('shield')}<h1>${esc(title)}</h1><p>${esc(description)}</p>${actor()?.status==='disabled'?'<p class="field-help">請使用總後台啟用帳號，或在上方選擇其他演示帳號。</p>':session.signedOut?btn('登入演示帳號','session-signin','primary'):btn('返回工作台','home','secondary')}</div></section>`;}
  const viewPermissions={dashboard:'requests.read',requests:'requests.read',detail:'requests.read',suppliers:'suppliers.read',whatsapp:'whatsapp.read',logs:'audit.read',system:'accounts.read',accounts:'accounts.read',admins:'admins.manage',permissions:'roles.manage','access-audit':'audit.read'};
  function scopedEvents(){if(isStaff())return can('audit.read')?state.events:[];const ids=new Set(ui.role==='teacher'?visibleRequests().map(r=>r.id):state.requests.filter(r=>r.invitations.some(i=>i.supplierId===ui.supplierId)).map(r=>r.id));return state.events.filter(e=>ids.has(e.requestId));}
  function guardAction(action,el){
    const permissions={approve:'suppliers.review',suspend:'suppliers.review','confirm-suspend':'suppliers.review',dispatch:'requests.manage','close-request':'requests.manage','confirm-close':'requests.manage','review-quote':'requests.manage','deliver-stage':'requests.manage',export:'reports.export','wa-compose':'whatsapp.send','wa-send':'whatsapp.send','wa-fail':'whatsapp.send','wa-retry':'whatsapp.send','wa-view':'whatsapp.read','wa-tab':'whatsapp.read','wa-filter':'whatsapp.read','open-whatsapp':'whatsapp.read','review-suppliers':'suppliers.read'};
    if(permissions[action])requirePermission(permissions[action]);
    if(['new','previous-step','send-otp','remove-file'].includes(action))requireActive('teacher');
    if(['toggle-shortlist'].includes(action))requireOwnRequest(state.requests.find(r=>r.id===(el.dataset.id||ui.requestId)));
    if(['next-stage','edit-request','teacher-decision'].includes(action))requireManageRequest(state.requests.find(r=>r.id===el.dataset.id));
    if(['accept','quote-form','supplier-messages','withdraw'].includes(action)){requireSupplier();const r=state.requests.find(r=>r.id===el.dataset.id);if(!r?.invitations.some(i=>i.supplierId===ui.supplierId))throw Error('你未獲邀參與這份需求。');}
    if(['reset','confirm-reset'].includes(action)){requirePermission('roles.manage');if(ui.role!=='superadmin')throw Error('只限總後台重置整套演示資料。');}
    if(action==='detail'){const r=state.requests.find(r=>r.id===el.dataset.id);if(ui.role==='teacher')requireOwnRequest(r);else requirePermission('requests.read');}
  }
  function queueNotification(templateId,r,supplierId){
    const recipientType=window.IQWhatsApp.templates().find(t=>t.id===templateId)?.recipientType;
    return window.IQWhatsApp.queue(state,{templateId,requestId:r.id,recipientType,...(supplierId?{supplierId}:{})});
  }
  function eventText(e){return esc(e.text||e.message||e.action||e.type||'訂單狀態已更新');}
  function navigation(){
    let lists=ui.role==='teacher'?[['dashboard','grid','工作概覽'],['requests','list','我的需求'],['new','plus','新建報價需求']]:ui.role==='supplier'?[['dashboard','grid','邀請大廳'],['quotes','file','我的報價'],['profile','building','公司資料']]:ui.role==='superadmin'?[
      ['system','grid','總後台總覽','accounts.read'],['accounts','people','老師／供應商帳號','accounts.read'],['admins','shield','管理員控制','admins.manage'],['permissions','settings','角色與權限','roles.manage'],['access-audit','activity','帳號操作紀錄','audit.read'],['requests','list','需求管理','requests.read'],['suppliers','people','供應商審核','suppliers.read'],['whatsapp','message','WhatsApp 通知','whatsapp.read']
    ]:[['dashboard','grid','營運總覽','requests.read'],['requests','list','需求管理','requests.read'],['suppliers','people','供應商審核','suppliers.read'],['whatsapp','message','WhatsApp 通知','whatsapp.read'],['accounts','people','老師／供應商帳號','accounts.read'],['logs','activity','操作記錄','audit.read']];
    if(isStaff())lists=lists.filter(x=>can(x[3]));
    return lists.map(([v,i,n])=>`<button class="nav-item ${ui.view===v||(v==='requests'&&ui.view==='detail')?'active':''}" data-action="nav" data-view="${v}">${icon(i,'nav-icon')}<span>${n}</span></button>`).join('');
  }
  const redactContact = value => String(value || '').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '［聯絡資料已隱藏］').replace(/(?:\+?852[\s-]?)?\b[2-9]\d{3}[\s-]?\d{4}\b/g, '［電話已隱藏］');
  function anonymousQuote(value) {
    let result = String(value || '');
    state.suppliers.forEach(s => [s.name,s.contact,s.phone,s.email,s.br].filter(Boolean).forEach(v => { result=result.split(v).join('［供應商資料已隱藏］'); }));
    return redactContact(result);
  }
  const reviewLabels={pending:'待審核',valid:'符合要求',clarification:'待澄清',rejected:'不符合需求',expired:'已失效',reconfirmation:'需求更新待確認'};
  const invitationLabels={invited:'待回覆',accepted:'已接單',expired:'已過回覆期限',reply_expired:'邀請未回覆',missed:'已逾承諾期限',withdrawn:'已退出',released:'名額已釋放',declined:'已婉拒'};
  const validQuotes=r=>window.IQ.validQuotes(state,r);
  const deliveredQuotes=r=>window.IQ.deliveredQuotes(state,r);
  const shortlisted=r=>(r.shortlistedQuoteIds||[]).filter(id=>deliveredQuotes(r).some(q=>q.id===id));
  const requestOutcome=r=>({zero:'暫無有效報價',partial:'有效報價不足目標',target:'已達有效報價目標'}[window.IQ.outcome(state,r)]);
  const collecting=r=>['matching','collecting'].includes(r.status);
  const localInput=value=>{const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  const extendedDeadline=r=>localInput(Math.max(Date.now(),new Date(r.deadline).getTime())+48*3600000);
  function requireManageRequest(r){if(ui.role==='teacher')requireOwnRequest(r);else requirePermission('requests.manage');if(!r)throw Error('找不到這份需求。');}
  function synchronizeDeadlines() {
    const changed=window.IQ.processDeadlines(state);
    if(window.IQWhatsApp.syncWorkflow)window.IQWhatsApp.syncWorkflow(state);
    return !!changed;
  }
  function render(){
    window.IQ.ensureWorkflow(state);
    initializeSession();
    window.IQWhatsApp.ensure(state);
    synchronizeDeadlines();
    const initials=actor()?.name?.slice(0,1)||'訪';
    $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="./index.html" aria-label="返回 InstiQuote AI 官網"><span class="brand-mark">${icon('book')}</span><span><span class="brand-name">InstiQuote<span> AI</span></span><span class="brand-tag">讓校園採購，更從容</span></span></a><div class="nav-section">${roleName[ui.role]}</div><nav aria-label="主導航">${navigation()}</nav><div class="nav-section">支持與資源</div><button class="nav-item ${ui.view==='guide'?'active':''}" data-action="nav" data-view="guide">${icon('help')}<span>使用指南</span></button><a class="nav-item" href="./index.html">${icon('building')}<span>公司官網</span></a><div class="sidebar-bottom"><div class="demo-note">${icon('shield')}<strong>為教育而設計</strong><p>匿名匹配 · 獨立報價<br>把更多時間留給教學</p></div>${ui.role==='superadmin'&&can('roles.manage')?`<button class="nav-item" data-action="reset">${icon('rotate')}<span>重置演示數據</span></button>`:''}<div class="app-footer">© ${new Date().getFullYear()} InstiQuote AI</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>工作空間</span>${icon('chevron')}<strong>${roleName[ui.role]}</strong></div><div class="topbar-actions"><div class="role-switch" aria-label="切換演示角色">${[['teacher','老師'],['supplier','供應商'],['admin','管理員'],['superadmin','總後台']].map(([r,n])=>`<button class="${ui.role===r?'active':''}" data-action="role" data-role="${r}">${n}</button>`).join('')}</div><button class="icon-button" data-action="notifications" aria-label="查看通知">${icon('bell')}<span class="notification-count">${Math.min(scopedEvents().length,9)}</span></button><span class="avatar" aria-label="演示用户">${initials}</span></div>${ui.notifications?notifications():''}</header>${sessionBar()}<main class="main-content" id="main">${content()}</main><div class="demo-bar"><span>${icon('spark')} 可操作原型 · 數據僅保存在當前瀏覽器</span><span>登入、權限、WhatsApp、AI 與文件傳輸均為演示</span></div></div></div>`;
    document.title=`${roleName[ui.role]} · InstiQuote AI`;
  }
  function notifications(){return `<section class="notifications-popover" aria-label="最近通知"><div class="panel-header"><strong>最近動態</strong>${btn('關閉','notifications','ghost small')}</div>${scopedEvents().slice(0,5).map(e=>`<div class="notification-item">${icon('bell')}<div>${eventText(e)}<div class="muted">${date(e.at||e.createdAt||Date.now(),true)}</div></div></div>`).join('')||'<p class="panel-body muted">暫無通知</p>'}</section>`;}
  function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function content(){
    if(!active())return denied(actor()?.status==='disabled'?'帳號已停用':'請登入演示帳號',session.signedOut?'你已登出演示或登入狀態已被重設。':'目前沒有可用的演示帳號。');
    if(ui.view==='guide')return guide();
    if(isStaff()){
      if(viewPermissions[ui.view]&&!can(viewPermissions[ui.view]))return denied();
      if(['system','accounts','admins','permissions','access-audit'].includes(ui.view))return accountView.dashboard(ui.view);
    }
    if(ui.view==='new')return ui.role==='teacher'?newRequest():denied();
    if(ui.view==='detail')return detail();
    if(ui.role==='teacher')return teacherDashboard();
    if(ui.role==='supplier')return supplierDashboard();
    return adminDashboard();
  }
  function stats(items){return `<div class="stats-grid">${items.map(([label,value,foot,i])=>`<div class="stat-card"><div class="stat-label">${label}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`).join('')}</div>`;}
  function teacherDashboard(){
    const requests=visibleRequests();
    return heading('YOUR SCHOOL, SIMPLIFIED',esc(actor().name)+'，歡迎回來','有效報價分批交付，讓老師按需要比較與洽談。',btn('新建報價需求','new','primary','plus'))+
      (ui.view==='dashboard'?`<section class="hero-banner"><div class="hero-copy"><div class="hero-kicker">更有條理的校園詢價</div><h2 class="hero-title">先看合適的報價，<br>再談合適的方案。</h2><p class="hero-description">不足目標也可先收到有效報價。<br>其餘繼續尋找，您可挑選 1 至 3 間供應商細談。</p><div class="hero-pills"><span class="pill">${icon('shield')}有效報價才交付</span><span class="pill">${icon('clock')}分階段跟進</span><span class="pill">${icon('people')}老師自主篩選</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-dot"></div><div class="art-card art-card-back"></div><div class="art-card"><div class="art-card-logo">${icon('book')} InstiQuote</div><div class="art-line"></div><div class="art-line short"></div><div class="art-quote">第 1 階段 <span>有效報價交付</span></div><div class="art-check">${icon('check')} 不足部分繼續尋找</div></div><div class="art-stamp">${icon('shield')}</div></div></section>`:'')+
      stats([['全部需求',requests.length,'每一份需求，清晰可追蹤','file'],['報價收集中',requests.filter(collecting).length,'不足部分可開始下一階段','clock'],['已交付有效報價',requests.reduce((n,r)=>n+deliveredQuotes(r).length,0),'已開放所有交付公司的聯絡資料','list'],['已建立洽談名單',requests.filter(r=>shortlisted(r).length).length,'每份需求最多 3 間，並非確認成交','people']])+
      `<div class="content-grid"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">我的報價需求 <span class="muted">${requests.length}</span></h2><p class="panel-subtitle">分階段收集、比較及洽談</p></div>${ui.view==='dashboard'?btn('查看全部','all-requests','ghost small'):''}</div>${filterBar()}<div class="request-list" id="request-list">${requestCards()}</div></section><aside class="stack">${tipsPanel()}${activityPanel()}</aside></div>`;
  }
  function filterBar(){return `<div class="filter-bar"><div class="tabs" aria-label="篩選需求">${[['all','全部'],['collecting','收集中'],['ready','已交付'],['shortlisted','洽談中'],['cancelled','已取消']].map(([k,t])=>`<button class="tab ${ui.filter===k?'active':''}" data-action="filter" data-filter="${k}">${t}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="request-search" placeholder="搜索需求或編號" aria-label="搜索需求或編號" value="${esc(ui.search)}"></label></div>`;}
  function filtered(){return visibleRequests().filter(r=>(ui.filter==='all'||(ui.filter==='collecting'?collecting(r):ui.filter==='ready'?deliveredQuotes(r).length>0:ui.filter==='shortlisted'?shortlisted(r).length>0:r.status===ui.filter))&&(!ui.search||[r.title,r.id,r.category].join(' ').toLowerCase().includes(ui.search.toLowerCase())));}
  function requestCards(){return filtered().map(r=>{const delivered=deliveredQuotes(r).length;return `<article class="request-card"><div class="request-top"><div class="request-category"><span class="category-icon">${icon(categoryIcon(r.category))}</span><span>${esc(r.category)}</span></div>${badge(r)}</div><h3 class="request-title"><button data-action="detail" data-id="${r.id}">${esc(r.title)}</button></h3><div class="request-meta"><span>${icon('pin')}${esc(r.district)}</span><span>${icon('calendar')}${date(r.deadline)} 收集截止</span><span>第 ${r.stage} 階段 · v${r.revision}</span></div><div class="progress-label"><span>已交付有效報價 <strong>${delivered}<span class="muted"> / ${r.targetQuotes}</span></strong></span><span>${r.status==='cancelled'?'已取消':requestOutcome(r)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(delivered/r.targetQuotes*100,100)}%"></div></div><div class="request-bottom"><span class="muted">${r.id}${shortlisted(r).length?' · '+shortlisted(r).length+' 間洽談中':''}</span>${btn(delivered?'比較及聯絡供應商':'查看進度','detail',delivered?'primary small':'secondary small','',`data-id="${r.id}"`)}</div></article>`;}).join('')||`<div class="empty-state">${icon('search')}<h3>沒有找到相關需求</h3><p>試試其他關鍵詞，或發佈一份新需求。</p>${btn('新建報價需求','new','primary','plus')}</div>`;}
  function tipsPanel(){return `<section class="panel side-panel"><div class="panel-header"><h2 class="panel-title">從需求到好方案</h2>${icon('spark')}</div><div class="panel-body steps-list">${[['發佈需求','說清服務內容、日期和人數。'],['分批收取有效報價','只有符合要求的方案交付，不足部分繼續尋找。'],['比較並聯絡','查看所有已交付公司的聯絡，挑選 1 至 3 間細談。']].map(([t,p],i)=>`<div class="step-item"><span class="step-number">${i+1}</span><div class="step-copy"><strong>${t}</strong><p>${p}</p></div></div>`).join('')}<a class="button secondary small sample-link" href="./quote-sample.html">查看報價比較樣本</a><div class="notice">${icon('shield')}洽談名單是跟進備忘，並不代表確認成交。學校及老師聯絡資料不會自動公開予供應商。</div></div></section>`;}
  function activityPanel(){return `<section class="panel side-panel"><div class="panel-header"><h2 class="panel-title">最近動態</h2>${icon('activity')}</div><div class="panel-body activity-list">${scopedEvents().slice(0,4).map(e=>`<div class="activity-item"><span class="activity-dot"></span><div class="activity-copy">${eventText(e)}<div class="activity-time">${date(e.at||e.createdAt||Date.now(),true)}</div></div></div>`).join('')||'<p class="muted">暫無動態</p>'}</div></section>`;}
  function field(label,name,value,type='text',help='',required=true){return `<label class="field"><span class="field-label">${label} ${required?'<span class="required">*</span>':''}</span><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="1"':''}>${help?`<span class="field-help">${help}</span>`:''}</label>`;}
  function selectField(label,name,value,options){return `<label class="field"><span class="field-label">${label} <span class="required">*</span></span><select class="select" name="${name}">${options.map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`;}
  function newRequest(){prepareTeacherDraft();return heading('NEW REQUEST','發佈一份報價需求','告訴我們您的需要，剩下的交給平台。',btn('返回工作台','home','ghost'))+`<div class="wizard-steps">${['描述需求','聯繫資料','確認發佈'].map((s,i)=>`<div class="wizard-step ${ui.step===i+1?'active':ui.step>i+1?'done':''}"><span>${ui.step>i+1?icon('check'):i+1}</span>${s}</div>`).join('')}</div><div class="form-layout"><form id="request-form" class="panel form-card"><div class="panel-header"><div><h2 class="panel-title">${['您的採購需求','方便我們聯繫您','發佈前，再檢查一次'][ui.step-1]}</h2><p class="panel-subtitle">${['儘量寫清楚內容，供應商才能提供準確報價。','資料只供平台跟進，不會自動向供應商公開。','確認後，系統會邀請符合條件的供應商。'][ui.step-1]}</p></div><span class="badge gray">${ui.step} / 3</span></div><div class="panel-body">${ui.step===1?requestStepOne():ui.step===2?requestStepTwo():requestReview()}</div><div class="form-actions"><span class="muted">${ui.step===1?'帶 * 的項目為必填':ui.step===2?'演示驗證碼：123456':'您可以隨時在工作台查看進度'}</span><div>${ui.step>1?btn('上一步','previous-step','secondary'):''}<button class="button primary" type="submit">${ui.step===3?'確認發佈需求':'下一步'}</button></div></div></form><aside class="stack">${tipsPanel()}<div class="notice warning">${icon('file')}演示附件僅保存文件名，不上傳或傳輸文件內容。</div></aside></div>`;}
  function requestStepOne(){return `<div class="form-grid">${field('需求名稱','title',draft.title,'text','例如：小四 STEM 機械人體驗課程')}${selectField('服務類別','category',draft.category,['到校課程','到校活動','印刷製作','小型維修'])}${selectField('服務地區','district',draft.district,['九龍城區','沙田區','觀塘區','中西區','屯門區'])}${field('參考預算（港幣）','budget',draft.budget,'number','選填，幫助供應商準備合適方案。',false)}<label class="field full"><span class="field-label">詳細需求 <span class="required">*</span></span><textarea class="textarea" name="description" rows="5" required placeholder="請描述活動日期、人數、年級、服務內容及特殊要求……">${esc(draft.description)}</textarea><span class="field-help">請避免在這裏填寫學校名稱、電話或電郵。</span></label><div class="field full"><span class="field-label">老師收集報價時間</span><div class="radio-cards">${[[72,'標準 · 3 天'],[48,'加急 · 48 小時'],[24,'加急 · 24 小時']].map(([h,l])=>`<label class="radio-card ${Number(draft.deadlineHours)===h?'selected':''}"><input type="radio" name="deadlineHours" value="${h}" ${Number(draft.deadlineHours)===h?'checked':''}>${icon('clock')}<strong>${l}</strong></label>`).join('')}</div><span class="field-help">加急選項供原型體驗，正式上線前需驗證供應商響應能力。</span></div><div class="field full"><span class="field-label">參考附件（選填）</span><label class="upload-zone">${icon('upload')}<strong>點擊選擇參考文件</strong><span>PDF、Word 或圖片 · 每份不超過 10 MB</span><input id="attachment-input" type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg" multiple hidden></label><div class="upload-list">${draft.files.map((f,i)=>`<div class="upload-item">${icon('file')}<span>${esc(f.name)}</span><button type="button" class="icon-button" data-action="remove-file" data-index="${i}" aria-label="移除 ${esc(f.name)}">${icon('close')}</button></div>`).join('')}</div></div></div>`;}
  function requestStepTwo(){return `<div class="notice">${icon('shield')}先填寫資料，再使用演示驗證碼完成驗證。</div><div class="form-grid" style="margin-top:24px">${field('學校名稱','school',draft.school,'text','演示可填寫：啓明學校')}${field('老師姓名','teacher',draft.teacher)}${field('聯繫電話','phone',draft.phone,'tel')}${field('聯繫電郵','email',draft.email,'email')}<div class="field full"><span class="field-label">手機驗證 <span class="required">*</span></span><div class="heading-actions"><input class="input" name="otp" inputmode="numeric" maxlength="6" placeholder="輸入 123456" aria-label="演示驗證碼" style="max-width:220px" ${draft.verified?'value="123456"':''}>${btn('獲取演示驗證碼','send-otp','secondary')}</div><span class="field-help">原型不會發送真實短信；演示驗證碼為 123456。</span></div></div>`;}
  function requestReview(){return `<div class="summary-grid">${[['需求名稱',draft.title],['服務類別',draft.category],['服務地區',draft.district],['收集時間',draft.deadlineHours+' 小時'],['參考預算',draft.budget?money(draft.budget):'未設預算'],['學校',draft.school],['聯繫人',draft.teacher],['聯繫電郵',draft.email]].map(([k,v])=>`<div class="summary-item"><span class="summary-label">${k}</span><strong class="summary-value">${esc(v)}</strong></div>`).join('')}</div><div class="form-section"><span class="summary-label">詳細需求</span><p style="white-space:pre-wrap">${esc(draft.description)}</p></div>${draft.files.length?`<p class="muted">${icon('file')} ${draft.files.length} 份演示附件</p>`:''}<label class="checkbox-row"><input type="checkbox" name="consent" required>我已檢查需求內容，並同意平台按本次需求進行匹配。</label>`;}
  function detail(){
    const r=request();if(r&&!(ui.role==='teacher'?ownRequest(r):isStaff()&&can('requests.read')))return denied();
    if(!r)return `<div class="empty-state"><h2>找不到這份需求</h2>${btn('返回工作台','home','primary')}</div>`;
    const shown=isStaff()?r.quotes:deliveredQuotes(r),valid=validQuotes(r),delivered=deliveredQuotes(r);
    return heading(r.id,esc(r.title),`${esc(r.category)} · ${esc(r.district)} · v${r.revision} · 第 ${r.stage} 階段`,btn('返回列表','back-list','secondary'))+
      `<div class="detail-grid"><div class="stack"><section class="panel"><div class="panel-header"><h2 class="panel-title">分階段收集進度</h2>${badge(r)}</div><div class="panel-body"><div class="workflow-result ${r.status==='cancelled'?'is-cancelled':''}"><div><span class="summary-label">目前結果</span><h3>${r.status==='cancelled'?'需求已取消':requestOutcome(r)}</h3><p>${r.status==='cancelled'?'已停止派單、收集及提醒。':collecting(r)?'已交付的有效報價可先比較，其餘繼續收集。':'本階段已結束，可接受現有結果，或延期開始下一階段。'}</p></div><strong>${delivered.length}<span> / ${r.targetQuotes} 份已交付</span></strong></div><div class="summary-grid"><div class="summary-item"><span class="summary-label">已確認接單</span><strong>${countAccepted(r)} 間</strong></div><div class="summary-item"><span class="summary-label">有效報價${isStaff()?'（含未交付）':''}</span><strong>${isStaff()?valid.length:delivered.length} 份</strong></div>${isStaff()?`<div class="summary-item"><span class="summary-label">待審核／澄清</span><strong>${r.quotes.filter(q=>['pending','clarification','reconfirmation'].includes(q.reviewStatus)).length} 份</strong></div>`:''}<div class="summary-item"><span class="summary-label">老師收集截止時間</span><strong>${date(r.deadline,true)}</strong></div></div></div></section>${ui.role==='teacher'?contactCard(r):''}<section class="panel"><div class="panel-header"><div><h2 class="panel-title">${isStaff()?'報價審核與交付':'已交付報價與供應商聯絡'}</h2><p class="panel-subtitle">${isStaff()?'只有目前需求版本、未過期且符合要求的有效報價才計入目標。':'各公司可用自己的報價格式；請按內容及需要自行篩選。'}</p></div><span class="badge green">${shown.length} 份${isStaff()?'已提交':'有效報價'}</span></div><div class="panel-body">${!shown.length?`<div class="empty-state">${icon('clock')}<h3>${isStaff()?'尚未收到報價':'尚未交付有效報價'}</h3><p>${isStaff()?'供應商提交後，請審核是否符合需求。':'平台會先審核需求符合度，再按階段交付。'}</p></div>`:`<div class="quote-grid">${shown.map(q=>quoteCard(r,q)).join('')}</div>`}</div></section>${stageHistory(r)}${isStaff()?invitationProgress(r):''}<section class="panel"><div class="panel-header"><h2 class="panel-title">需求詳情 · v${r.revision}</h2></div><div class="panel-body"><p class="preserve-lines">${esc(r.description)}</p><div class="summary-grid"><div class="summary-item"><span class="summary-label">參考預算</span><strong>${r.budget?money(r.budget):'未設預算'}</strong></div><div class="summary-item"><span class="summary-label">學校（僅老師及管理員可見）</span><strong>${esc(r.school)}</strong></div></div>${r.files?.length?`<p class="muted">參考附件：${r.files.map(f=>esc(f.name)).join('、')}（演示僅記錄文件名）</p>`:''}${versionHistory(r)}</div></section>${messagesPanel(r,isStaff()?'admin':'teacher')}</div><aside class="stack">${isStaff()?adminActions(r):teacherActions(r)}${tipsPanel()}${activityPanel()}</aside></div>`;
  }
  function quoteCard(r,q){
    const listed=shortlisted(r).includes(q.id),s=supplier(q.supplierId),delivered=deliveredQuotes(r).some(x=>x.id===q.id),manageable=isStaff()&&can('requests.manage')&&r.status!=='cancelled';
    return `<article class="quote-card ${listed?'selected':''}" data-quote-id="${q.id}"><div class="quote-card-top"><span class="quote-code">${esc(s?.name||q.code)}</span><span class="badge ${q.reviewStatus==='valid'?'green':q.reviewStatus==='rejected'?'red':'amber'}">${esc(reviewLabels[q.reviewStatus]||q.reviewStatus)}</span></div><div class="quote-price">${money(q.amount)}</div><p class="preserve-lines">${esc(q.description)}</p><div class="quote-features"><span>${icon('calendar')}有效期 ${q.validDays||30} 天</span><span>${icon('clock')}${date(q.submittedAt,true)} 提交 · v${q.requestRevision}</span>${q.attachmentName?`<span>${icon('file')}${esc(q.attachmentName)}（文件名演示）</span>`:''}</div>${q.reviewReason?`<p class="quote-review-reason"><strong>審核／澄清：</strong>${esc(q.reviewReason)}</p>`:''}<div class="quote-contact"><span class="summary-label">${isStaff()?'供應商資料':'可直接聯絡此供應商'}</span><strong>${esc(s?.contact||'未提供聯絡人')}</strong><span>${esc(s?.phone||'')}</span><span>${esc(s?.email||'')}</span><small>以上為模擬聯絡資料</small></div><div class="quote-footer workflow-quote-footer">${isStaff()?`<span class="badge ${delivered?'green':'gray'}">${delivered?'已交付老師':'未交付'}</span>${manageable?btn('審核報價','review-quote','secondary small','',`data-id="${r.id}" data-quote="${q.id}"`):''}`:r.status!=='cancelled'?btn(listed?'移出洽談名單':'加入洽談名單','toggle-shortlist',listed?'secondary small':'primary small','',`data-id="${r.id}" data-quote="${q.id}"`):'<span class="muted">需求已取消</span>'}</div>${isStaff()&&q.revisions?.length?`<details class="workflow-history"><summary>${q.revisions.length} 次報價修訂紀錄</summary>${q.revisions.map(v=>`<p>${date(v.submittedAt||v.at||r.createdAt,true)} · ${money(v.amount)} · ${esc(reviewLabels[v.reviewStatus]||'舊版報價')}</p>`).join('')}</details>`:''}</article>`;
  }
  function contactCard(r){const ids=shortlisted(r);return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">洽談名單 <span class="muted">${ids.length} / 3</span></h2><p class="panel-subtitle">選 1 至 3 間進一步洽談，可隨時調整，並非確認成交。</p></div>${icon('people')}</div><div class="panel-body">${ids.length?`<div class="shortlist-items">${ids.map(id=>{const q=r.quotes.find(q=>q.id===id),s=supplier(q?.supplierId);return `<div><strong>${esc(s?.name||q?.code)}</strong><span>${money(q?.amount)}</span>${btn('移除','toggle-shortlist','ghost small','',`data-id="${r.id}" data-quote="${id}"`)}</div>`;}).join('')}</div>`:'<p class="muted">從下方已交付的有效報價加入洽談名單。所有已交付供應商的聯絡資料均可查看。</p>'}</div></section>`;}
  function stageHistory(r){return `<section class="panel"><div class="panel-header"><h2 class="panel-title">階段交付紀錄</h2><span class="badge gray">第 ${r.stage} 階段</span></div><div class="panel-body stage-records">${(r.stages||[]).map(stage=>`<article><span class="stage-number">第 ${stage.number} 階段</span><div><strong>${{collecting:'收集中',delivered:'已有交付',closed:'本階段結束'}[stage.status]||'收集中'}</strong><p>${stage.deliveredAt?date(stage.deliveredAt,true)+' 交付 · ':''}${(stage.quoteIds||[]).length} 份報價紀錄 · 需求 v${stage.revision||1}</p>${stage.reason?`<p>${esc(stage.reason)}</p>`:''}${(stage.deliveries||[]).length>1?`<p>本階段分 ${stage.deliveries.length} 批交付</p>`:''}</div></article>`).join('')}</div></section>`;}
  function invitationProgress(r){return `<section class="panel"><div class="panel-header"><h2 class="panel-title">供應商回覆與交報期限</h2><span class="badge gray">${r.invitations.length} 間參與紀錄</span></div><div class="panel-body invitation-progress">${r.invitations.map(i=>{const s=supplier(i.supplierId),q=r.quotes.find(q=>q.supplierId===i.supplierId);return `<article><div class="request-top"><strong>${esc(s?.name||i.supplierId)}</strong><span class="badge ${i.status==='accepted'?'blue':'gray'}">${esc(invitationLabels[i.status]||i.status)}</span></div><dl class="deadline-grid"><div><dt>邀請回覆期限</dt><dd>${date(i.replyDeadline,true)}</dd></div><div><dt>承諾交報時間</dt><dd>${i.quoteDueAt?date(i.quoteDueAt,true):'尚未接單'}</dd></div><div><dt>老師收集截止</dt><dd>${date(r.deadline,true)}</dd></div></dl><span class="field-help">第 ${i.stage||1} 階段 · ${q?reviewLabels[q.reviewStatus]||q.reviewStatus:'尚未交報'}${i.reason?' · '+esc(i.reason):''}</span></article>`;}).join('')||'<p class="muted">尚未有合適供應商，請調整需求或等待新的供應商。</p>'}</div></section>`;}
  function versionHistory(r){return `<details class="workflow-history"><summary>查看需求版本紀錄（${r.versions?.length||1} 版）</summary>${(r.versions||[]).map(v=>`<article><strong>v${v.revision} · ${esc(v.title)}</strong><p>${esc(v.reason||'初始需求')} · ${date(v.at||r.createdAt,true)}</p><p>${esc(v.category)} · ${esc(v.district)} · 截止 ${date(v.deadline,true)}</p><p class="preserve-lines">${esc(v.description)}</p></article>`).join('')}</details>`;}
  function teacherActions(r){const cancelled=r.status==='cancelled';return `<section class="panel"><div class="panel-header"><h2 class="panel-title">收集安排</h2></div><div class="panel-body stack"><div class="notice">${requestOutcome(r)}。老師可先與現有供應商洽談，或讓平台繼續尋找。</div>${!cancelled?`${deliveredQuotes(r).length?btn('接受現有結果並結束收集','teacher-decision','primary','check',`data-id="${r.id}" data-decision="accept"`):''}${btn('延期並開始下一階段','next-stage','secondary','clock',`data-id="${r.id}"`)}${btn('修改需求及延後交報','edit-request','secondary','file',`data-id="${r.id}"`)}${btn('取消需求','teacher-decision','ghost','',`data-id="${r.id}" data-decision="cancel"`)}<p class="field-help">變更會保存版本，提醒已參與供應商重新確認報價；全部安排均需記錄原因。</p>`:'<p class="muted">此需求已取消，紀錄保留供回看。</p>'}</div></section>`;}
  function messagesPanel(r,author){return `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">需求問答</h2><p class="panel-subtitle">通過平台溝通，避免在內容中填寫學校或聯絡資料。</p></div>${icon('message')}</div><div class="panel-body">${r.messages?.length?r.messages.map(m=>`<div class="notification-item"><span class="badge gray">${{teacher:'老師',supplier:'供應商',admin:'平台管理員'}[m.author]||'平台'}</span><div><p>${esc(author==='supplier'?redactContact(anonymize(m.text,r)):author==='teacher'?anonymousQuote(m.text):m.text)}</p><span class="activity-time">${date(m.at,true)}</span></div></div>`).join(''):'<p class="muted">暫無問題，有補充內容可以在這裏留言。</p>'}${r.status!=='cancelled'&&(author!=='admin'||can('requests.manage'))?`<form id="message-form" data-request="${r.id}" data-author="${author}" class="stack"><label class="field"><span class="field-label">補充説明或問題</span><textarea class="textarea" name="message" rows="2" maxlength="1000" required placeholder="填寫需要澄清的內容……"></textarea></label><div><button class="button secondary" type="submit">發送平台留言</button></div></form>`:'<p class="field-help">此需求或目前角色只可查看紀錄。</p>'}</div></section>`;}
  function supplierDashboard(){
    const company=supplier(ui.supplierId);if(!company)return denied('帳號未綁定公司','請由總後台設定供應商帳號的公司。');if(ui.view==='profile')return profile();
    if(company.status!=='approved')return heading('SUPPLIER WORKSPACE',company.status==='pending'?'公司審核中':'公司接單資格已暫停','你可以查看公司資料；審核通過後才可接單及提交報價。')+btn('查看公司資料','nav','secondary','building','data-view="profile"');
    const ownQuotes=state.requests.flatMap(r=>r.quotes.filter(q=>q.supplierId===company.id).map(q=>({r,q}))),invites=state.requests.filter(r=>r.invitations.some(i=>i.supplierId===company.id));
    return heading('SUPPLIER WORKSPACE',ui.view==='quotes'?'我的報價':'合適的需求，在這裏相遇','確認回覆期限與承諾交報時間，需求有更新時請重新確認報價。')+`<div class="panel supplier-picker"><span class="field-label">目前綁定公司</span><strong>${esc(company.name)}</strong><span class="badge green">已審核</span><span class="muted">公司由目前演示帳號決定，可在上方切換帳號體驗。</span></div>`+
      stats([['收到的邀請',invites.filter(collecting).length,'按需求類別及地區匹配','mail'],['已接單',invites.filter(r=>collecting(r)&&r.invitations.some(i=>i.supplierId===company.id&&i.status==='accepted')).length,'請按承諾時間交報','clock'],['已提交報價',ownQuotes.length,'修訂保留舊版供追蹤','file'],['服務評分',company.score,'演示分數，未啟用自動扣分','shield']])+
      `<section class="panel"><div class="panel-header"><div><h2 class="panel-title">${ui.view==='quotes'?'已提交的報價':'報價邀請及跟進'}</h2><p class="panel-subtitle">學校及老師的聯絡資料保持隱藏；報價格式可按公司慣用方式提供。</p></div><a class="button ghost small" href="./quote-sample.html">查看報價樣本</a></div><div class="request-list">${(ui.view==='quotes'?invites.filter(r=>r.quotes.some(q=>q.supplierId===company.id)):invites).map(r=>supplierRequestCard(r,company)).join('')||'<div class="empty-state"><h3>暫無匹配紀錄</h3><p>有合適需求時會在此顯示。</p></div>'}</div></section>`;
  }
  function supplierRequestCard(r,s){
    const i=r.invitations.find(i=>i.supplierId===s.id),q=r.quotes.find(q=>q.supplierId===s.id),open=collecting(r)&&new Date(r.deadline)>new Date(),canAccept=open&&i.status==='invited'&&new Date(i.replyDeadline)>new Date(),canQuote=open&&i.status==='accepted';
    return `<article class="request-card" data-supplier-request="${r.id}"><div class="request-top"><span class="request-category">${icon(categoryIcon(r.category))}${esc(r.category)}</span><span class="badge ${r.status==='cancelled'?'red':q?.reviewStatus==='valid'?'green':'amber'}">${r.status==='cancelled'?'需求已取消':q?esc(reviewLabels[q.reviewStatus]||q.reviewStatus):esc(invitationLabels[i.status]||i.status)}</span></div><h3>${esc(anonymize(r.title,r))}</h3><div class="request-meta"><span>${icon('pin')}${esc(r.district)}</span><span>需求 v${r.revision} · 第 ${r.stage} 階段</span><span>${r.id}</span></div>${q?.reviewStatus==='reconfirmation'?'<div class="notice warning">需求內容已更新，原報價暫不計入有效報價；請查看新內容及延後的交報時間，再修訂提交。</div>':''}<p class="preserve-lines">${esc(anonymize(r.description,r))}</p><dl class="deadline-grid"><div><dt>邀請回覆期限</dt><dd>${date(i.replyDeadline,true)}</dd></div><div><dt>承諾交報時間</dt><dd>${(i.status==='accepted'||q)&&i.quoteDueAt?date(i.quoteDueAt,true):'接單時設定'}</dd></div><div><dt>老師收集截止</dt><dd>${date(r.deadline,true)}</dd></div></dl>${q?`<div class="supplier-quote-summary"><strong>${money(q.amount)}</strong><p class="preserve-lines">${esc(q.description)}</p>${q.reviewReason?`<p><strong>審核／澄清：</strong>${esc(q.reviewReason)}</p>`:''}<span class="field-help">報價第 ${q.quoteRevision||1} 版 · 對應需求 v${q.requestRevision} · ${shortlisted(r).includes(q.id)?'老師已加入洽談名單（未確認成交）':deliveredQuotes(r).some(x=>x.id===q.id)?'已交付老師':'待審核或待交付'}</span>${q.revisions?.length?`<details class="workflow-history"><summary>查看 ${q.revisions.length} 次報價修訂紀錄</summary>${q.revisions.map(v=>`<p>${money(v.amount)} · ${esc(reviewLabels[v.reviewStatus]||'舊版')} · ${date(v.submittedAt||r.createdAt,true)}</p>`).join('')}</details>`:''}</div>`:''}<div class="request-bottom"><span class="muted">${r.status==='cancelled'?'已停止所有收集操作':open?invitationLabels[i.status]||i.status:'本階段已結束'}</span><div class="workflow-actions">${canAccept?btn('確認接單','accept','primary small','check',`data-id="${r.id}"`):''}${canQuote?btn(q?'修訂並重新提交報價':'填寫報價','quote-form','primary small','file',`data-id="${r.id}"`):''}${open&&['accepted','invited'].includes(i.status)?btn('退出本次需求','withdraw','ghost small','',`data-id="${r.id}"`):''}${i.status==='accepted'&&r.status!=='cancelled'?btn('需求問答','supplier-messages','ghost small','message',`data-id="${r.id}"`):''}</div></div></article>`;
  }
  function profile(){const s=supplier(ui.supplierId);return heading('COMPANY PROFILE','公司資料','以下為演示公司資料。正式版將通過商户賬户管理。')+`<section class="panel"><div class="panel-header"><h2>${esc(s.name)}</h2><span class="badge ${s.status==='approved'?'green':'amber'}">${{approved:'已審核',pending:'審核中',suspended:'已停權'}[s.status]}</span></div><div class="panel-body summary-grid">${[['商業登記號碼',s.br],['聯繫人',s.contact],['電話',s.phone],['電郵',s.email],['服務類別',s.category.join('、')],['服務地區',s.districts.join('、')],['會員狀態',{paid:'付費會員',trial:'試用會員',free:'免費會員'}[s.plan]],['剩餘試用次數',s.trialRemaining]].map(([k,v])=>`<div class="summary-item"><span class="summary-label">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></section>`;}
  function adminDashboard(){if(ui.view==='whatsapp')return waView.dashboard();if(ui.view==='suppliers')return supplierReview();if(ui.view==='logs')return logs();return heading('OPERATIONS OVERVIEW',ui.view==='requests'?'需求管理':'平台營運總覽','跟進每一份需求，讓報價收集有序進行。',(can('whatsapp.read')?btn('WhatsApp 通知','open-whatsapp','primary','message'):'')+(can('reports.export')?btn('導出報表','export','secondary','download'):''))+stats([['全部需求',state.requests.length,'當前演示數據','file'],['待處理需求',state.requests.filter(r=>['matching','collecting'].includes(r.status)).length,'持續跟進派單及交付','clock'],['已審核供應商',state.suppliers.filter(s=>s.status==='approved').length,'按類別及服務地區匹配','people'],['待審核供應商',state.suppliers.filter(s=>s.status==='pending').length,'人工核對公司資料及 BR','shield']])+`<div class="content-grid"><section class="panel"><div class="panel-header"><h2 class="panel-title">需求與派單進度</h2>${btn('供應商審核','review-suppliers','ghost small')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>需求</th><th>狀態</th><th>接單／報價</th><th>截止時間</th><th>操作</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td><strong>${esc(r.title)}</strong><span class="field-help">${r.id} · ${esc(r.district)}</span></td><td>${badge(r)}</td><td>${countAccepted(r)} 接單 / ${validQuotes(r).length} 有效<br><span class="field-help">${r.quotes.length} 已交 · ${deliveredQuotes(r).length} 已交付 · 第 ${r.stage} 階段</span></td><td>${date(r.deadline,true)}</td><td>${btn('管理','detail','secondary small','',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><aside class="stack">${activityPanel()}<section class="panel"><div class="panel-header"><h2 class="panel-title">類別需求分佈</h2></div><div class="panel-body chart-bars">${['到校課程','到校活動','印刷製作','小型維修'].map(c=>{const n=state.requests.filter(r=>r.category===c).length;return `<div class="chart-row"><span>${c}</span><div class="chart-track"><div class="chart-fill" style="width:${n/state.requests.length*100}%"></div></div><strong>${n}</strong></div>`;}).join('')}</div></section></aside></div>`;}
  function adminActions(r){
    if(!can('requests.manage'))return `<section class="panel"><div class="panel-body"><h2 class="panel-title">唯讀模式</h2><p class="muted">此角色可以查看需求，不能審核、交付、補派或更改安排。</p></div></section>`;
    const cancelled=r.status==='cancelled';
    return `<section class="panel"><div class="panel-header"><h2 class="panel-title">收集與交付操作</h2></div><div class="panel-body stack"><div class="notice">先交付有效報價，不足的可在下一階段尋找；操作均保留原因與紀錄。</div>${!cancelled?`${btn('先交付目前有效報價','deliver-stage','primary','file',`data-id="${r.id}" ${validQuotes(r).length?'':'disabled'}`)}${btn('開始下一階段尋找供應商','next-stage','secondary','people',`data-id="${r.id}"`)}${btn('補派符合條件的供應商','dispatch','secondary','people',`data-id="${r.id}" ${collecting(r)?'':'disabled'}`)}${btn('結束本階段並交付有效報價','close-request','secondary','check',`data-id="${r.id}" ${collecting(r)?'':'disabled'}`)}${btn('修改需求及延後交報','edit-request','secondary','file',`data-id="${r.id}"`)}${btn('取消需求','teacher-decision','ghost','',`data-id="${r.id}" data-decision="cancel"`)}`:'<p class="muted">需求已取消，已停止派單、收集與提醒。</p>'}<div class="summary-item"><span class="summary-label">學校</span><strong>${esc(r.school)}</strong></div><div class="summary-item"><span class="summary-label">老師</span><strong>${esc(r.teacher)} · ${esc(r.phone)}</strong></div></div></section>`;
  }
  function supplierReview(){return heading('SUPPLIER MANAGEMENT','供應商審核','先核對公司資料，再開放接單權限。')+`<section class="panel"><div class="panel-header"><h2 class="panel-title">全部供應商</h2><span class="badge amber">${state.suppliers.filter(s=>s.status==='pending').length} 間待審核</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>公司／商業登記號碼</th><th>服務類別</th><th>評分</th><th>狀態</th><th>操作</th></tr></thead><tbody>${state.suppliers.map(s=>`<tr><td><strong>${esc(s.name)}</strong><span class="field-help">BR ${esc(s.br)}</span></td><td>${esc(s.category.join('、'))}</td><td>${s.score}</td><td><span class="badge ${s.status==='approved'?'green':s.status==='pending'?'amber':'red'}">${{approved:'已審核',pending:'待審核',suspended:'已停權'}[s.status]}</span></td><td>${can('suppliers.review')?(s.status==='approved'?btn('停權','suspend','ghost small','',`data-id="${s.id}"`):btn(s.status==='pending'?'批准':'恢復','approve','primary small','',`data-id="${s.id}"`)):'<span class="muted">唯讀</span>'}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function logs(){return heading('AUDIT TRAIL','操作記錄','查看派單、接單、報價及管理操作的時間線。',can('reports.export')?btn('導出報表','export','secondary','download'):'')+`<section class="panel"><div class="panel-body activity-list">${state.events.map(e=>`<div class="activity-item"><span class="activity-dot"></span><div class="activity-copy">${eventText(e)}<div class="activity-time">${date(e.at||e.createdAt||Date.now(),true)} ${esc(e.requestId||'')}</div></div></div>`).join('')}</div></section>`;}
  function guide(){return heading('GETTING STARTED','用一份需求，體驗完整流程','切換四種演示角色，體驗帳號管理及不同權限。')+`<div class="help-grid">${[['老師','book','創建需求，輸入演示驗證碼 123456，再發布。查看每階段已交付的有效報價與全部供應商聯絡，挑選 1 至 3 間進一步洽談。'],['供應商','people','在邀請大廳確認回覆期限、接單並承諾交報時間，按公司慣用格式提交方案。需求更新時修訂後重新交報。'],['管理員','shield','審核報價需求符合度、先交付有效報價，並在不足目標時安排下一階段與候補供應商。'],['總後台','settings','管理老師、供應商與管理員帳號，設定角色權限、停用帳號及查看操作紀錄。']].map(([t,i,p])=>`<section class="panel help-card">${icon(i)}<h2>${t}</h2><p>${p}</p></section>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-body"><h2>關於這個原型</h2><p>這是用於驗證業務流程的可操作演示。數據保存在當前瀏覽器，不會在不同設備或瀏覽器之間共享。</p><p>手機驗證、通知、AI 及附件傳輸尚未連接真實服務；附件只記錄文件名。請使用模擬資料體驗。</p><p>重置演示數據會恢復四份示例需求，並清除本地新增及修改。</p>${ui.role==='teacher'?btn('體驗新建需求','new','primary','plus'):''}</div></section>`;}
  function modal(title,body,footer=''){ $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="關閉">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('#modal-root input, #modal-root textarea, #modal-root button')?.focus(),0);}
  function closeModal(){ $('#modal-root').innerHTML=''; }
  function showQuoteForm(id){
    const r=state.requests.find(r=>r.id===id),q=r.quotes.find(q=>q.supplierId===ui.supplierId);if(r.status==='cancelled')throw Error('需求已取消，不能提交報價。');
    modal(q?'修訂並重新提交報價':'提交獨立報價',`<p class="muted">${esc(anonymize(r.title,r))} · 需求 v${r.revision}</p><div class="notice">公司可使用自己的報價格式。修訂會保留舊版，重新審核符合需求後才會交付老師。</div><form id="quote-form" data-request="${id}" data-revision="${r.revision}" data-quote-revision="${q?.quoteRevision||0}"><div class="form-grid">${field('報價總額（港幣）','amount',q?.amount||'','number')}${field('報價有效期（天）','validDays',q?.validDays||30,'number')}<label class="field full"><span class="field-label">方案內容及包含項目 <span class="required">*</span></span><textarea class="textarea" name="description" rows="6" required placeholder="按公司慣用方式說明服務內容。可補充數量、單價、額外費用、日期、人員、材料及付款條件。">${esc(q?.description||'')}</textarea></label><label class="field full"><span class="field-label">報價附件（選填）</span><input class="input" type="file" name="quoteAttachment" accept=".pdf,.doc,.docx"><span class="field-help">${q?.attachmentName?'目前文件名：'+esc(q.attachmentName)+'。 ':''}原型僅記錄文件名；不會上傳文件內容。</span></label><a class="sample-link" href="./quote-sample.html" target="_blank" rel="noopener">參考比較欄位樣本</a></div><div class="form-actions">${btn('取消','close-modal','secondary')}<button type="submit" class="button primary">${q?'保存修訂並重新交報':'提交待審報價'}</button></div></form>`);
  }
  function showWorkflowForm(action,r,quoteId){
    const reasonField=`<label class="field full"><span class="field-label">原因／跟進說明 <span class="required">*</span></span><textarea class="textarea" name="reason" rows="3" required maxlength="2000" placeholder="請記錄這次安排的原因……"></textarea></label>`;
    let title='',body='',submit='確認安排';
    if(action==='review'){
      const q=r.quotes.find(q=>q.id===quoteId);title='審核報價是否符合需求';submit='保存審核';body=`<p>${esc(supplier(q?.supplierId)?.name||q?.code)} · ${money(q?.amount)}</p><div class="notice">有效報價須符合目前版本需求、仍在有效期且公司資格可用。只有有效報價會計入目標及交付老師。</div><label class="field"><span class="field-label">審核狀態</span><select class="select" name="reviewStatus">${Object.entries(reviewLabels).map(([key,label])=>`<option value="${key}" ${q.reviewStatus===key?'selected':''}>${label}</option>`).join('')}</select></label>${reasonField}`;
    }else if(action==='next'){
      title=ui.role==='teacher'?'延期並開始下一階段':'開始下一階段尋找供應商';submit='確認延期及補派';body=`<div class="notice">先交付現有有效報價，保留已交付方案，再釋放未履約名額及尋找候補。若沒有新的合資格供應商，會如實顯示。</div>${field('延後的老師收集截止時間','deadline',extendedDeadline(r),'datetime-local','必須遲於目前截止時間，參與供應商的交報時間會延後。')}${reasonField}`;
    }else if(action==='edit'){
      title='更新需求並延後交報';submit='保存新版本並提醒供應商';body=`<div class="notice warning">更新會保存需求版本，已提交報價須重新確認。相關供應商將收到內容更新及延期提醒。</div><div class="form-grid">${field('需求名稱','title',r.title)}${selectField('服務類別','category',r.category,window.IQ.categories)}${selectField('服務地區','district',r.district,window.IQ.districts)}<label class="field"><span class="field-label">參考預算（港幣）</span><input class="input" name="budget" type="number" min="0" value="${r.budget||0}"></label><label class="field full"><span class="field-label">更新後的詳細需求 <span class="required">*</span></span><textarea class="textarea" name="description" rows="5" required>${esc(r.description)}</textarea></label>${field('延後的老師收集截止時間','deadline',extendedDeadline(r),'datetime-local','新截止時間須遲於舊截止及現在時間。')}${reasonField}</div>`;
    }else if(action==='accept-invitation'){
      title='確認接單及承諾交報時間';submit='確認接單';const due=new Date(Math.min(Date.now()+24*3600000,new Date(r.deadline).getTime()));body=`<p>${esc(anonymize(r.title,r))}</p>${field('承諾交報時間','quoteDueAt',localInput(due),'datetime-local','必須在老師收集截止時間之前。')}<p class="field-help">老師收集截止：${date(r.deadline,true)}</p>`;
    }else{
      const labels={deliver:'先交付目前有效報價',close:'結束本階段並交付有效報價',accept:'接受現有結果並結束收集',cancel:'取消這份需求',withdraw:'退出本次需求'};title=labels[action];submit=action==='cancel'?'確認取消需求':action==='withdraw'?'確認退出':'確認安排';body=`<p>${action==='deliver'?'只交付目前符合要求的有效報價，老師可先查看所有聯絡及建立洽談名單；其餘繼續收集。':action==='close'?'結束目前收集並交付有效報價。零報價、部分及足額結果會分開顯示，老師仍可申請下一階段。':action==='accept'?'接受現有有效報價並停止繼續收集。洽談名單仍可調整，此操作不代表確認成交。':action==='cancel'?'取消後停止派單、交報、留言及提醒，原有紀錄會保留，不會因此扣供應商分數。':'退出會釋放名額並保留原因，平台可安排候補供應商。'}</p>${reasonField}`;
    }
    modal(title,`<form id="workflow-form" data-operation="${action}" data-request="${r.id}" data-revision="${r.revision}" ${quoteId?`data-quote="${quoteId}" data-quote-revision="${r.quotes.find(q=>q.id===quoteId)?.quoteRevision||1}"`:''} class="stack">${body}<div class="form-actions">${btn('返回','close-modal','secondary')}<button type="submit" class="button ${action==='cancel'||action==='withdraw'?'danger':'primary'}">${submit}</button></div></form>`);
  }
  function handleWorkflowSubmit(form){
    const r=state.requests.find(r=>r.id===form.dataset.request),operation=form.dataset.operation,fd=new FormData(form),reason=String(fd.get('reason')||'').trim();
    if(['accept-invitation','withdraw'].includes(operation)){requireSupplier();if(!r?.invitations.some(i=>i.supplierId===ui.supplierId))throw Error('你未獲邀參與這份需求。');}else if(['review','deliver','close'].includes(operation))requirePermission('requests.manage');else requireManageRequest(r);
    if(Number(form.dataset.revision)!==r.revision)throw Error('需求已更新，請重新開啟表單查看最新版本。');
    if(operation!=='accept-invitation'&&!reason)throw Error('請記錄原因或跟進說明。');
    const deadline=fd.get('deadline')?new Date(fd.get('deadline')).toISOString():null;
    if(operation==='review'&&Number(form.dataset.quoteRevision)!==(r.quotes.find(q=>q.id===form.dataset.quote)?.quoteRevision||1))throw Error('供應商已修訂這份報價，請重新查看內容後再審核。');
    if(operation==='review')window.IQ.reviewQuote(state,r.id,form.dataset.quote,fd.get('reviewStatus'),reason);
    if(operation==='deliver')window.IQ.deliverStage(state,r.id,reason);
    if(operation==='close')window.IQ.closeRequest(state,r.id,reason);
    if(operation==='next'){if(ui.role==='teacher')window.IQ.teacherDecision(state,r.id,'extend',{deadline,reason});else window.IQ.startNextStage(state,r.id,{deadline,reason});}
    if(operation==='edit')window.IQ.updateRequest(state,r.id,{title:fd.get('title'),category:fd.get('category'),district:fd.get('district'),description:fd.get('description'),budget:Number(fd.get('budget')),deadline,reason});
    if(['accept','cancel'].includes(operation))window.IQ.teacherDecision(state,r.id,operation,{reason});
    if(operation==='withdraw')window.IQ.withdrawInvitation(state,r.id,ui.supplierId,reason);
    if(operation==='accept-invitation'){window.IQ.acceptInvitation(state,r.id,ui.supplierId,new Date(fd.get('quoteDueAt')).toISOString());queueNotification('supplier_confirmed',r);}
    closeModal();render();toast(operation==='next'?`已開始第 ${r.stage} 階段；可用候補及新邀請請查看進度。`:operation==='edit'?'已保存新版本，供應商更新及延期提醒已加入演示佇列。':operation==='review'?'審核已保存，只有有效報價計入目標。':operation==='withdraw'?'已退出並釋放名額。':operation==='accept-invitation'?'已確認接單，請按承諾時間交報。':'安排已保存，相關演示通知已更新。');
  }
  function prepareTeacherDraft(){
    const a=actor();if(!a||ui.role!=='teacher')return;
    if(draft.ownerAccountId&&draft.ownerAccountId!==a.id){
      try{localStorage.setItem('instiquote-draft-'+draft.ownerAccountId,JSON.stringify(draft));draft=JSON.parse(localStorage.getItem('instiquote-draft-'+a.id)||'null')||{};}catch{draft={};}
    }
    draft={title:'',category:'到校課程',district:'九龍城區',description:'',budget:'',deadlineHours:72,files:[],verified:false,...draft,ownerAccountId:a.id};
    for(const [field,value] of [['school',a.school],['teacher',a.name],['phone',a.phone],['email',a.email]])if(!draft[field])draft[field]=value;
  }
  function saveDraft(){try{localStorage.setItem('instiquote-draft',JSON.stringify(draft));if(draft.ownerAccountId)localStorage.setItem('instiquote-draft-'+draft.ownerAccountId,JSON.stringify(draft));}catch{}}
  function captureDraft(form){const fd=new FormData(form);for(const k of ['title','category','district','description','budget','deadlineHours','school','teacher','phone','email'])if(fd.has(k))draft[k]=fd.get(k);saveDraft();}
  function navigate(view){ui.view=view;ui.notifications=false;ui.filter='all';ui.search='';render();window.scrollTo({top:0,behavior:'smooth'});}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action;safe(()=>{
    syncExternalState();
    if(a==='role'){switchRole(el.dataset.role);return;}
    if(a==='session-signout'){if(active())window.IQAccess.record(state,actor().id,'demo_logout',actor().id,'登出演示帳號');session.signedOut=true;saveSession();closeModal();render();toast('已登出演示帳號。');return;}
    if(a==='session-signin'){const account=actor();if(!account||account.status!=='active')throw Error('這個演示帳號已停用。');session.signedOut=false;session.revisions[account.id]=account.loginRevision;account.lastLoginAt=new Date().toISOString();window.IQAccess.record(state,account.id,'demo_login',account.id,'登入演示帳號');saveSession();navigate(roleHome());return;}
    if(a!=='close-modal')requireActive();
    guardAction(a,el);
    if(accountView.handleClick(el))return;
    if(waView.handleClick(el))return;
    if(a==='open-whatsapp')navigate('whatsapp');
    if(a==='nav')navigate(el.dataset.view);
    if(a==='home')navigate(roleHome());

    if(a==='notifications'){ui.notifications=!ui.notifications;render();}
    if(a==='new'){prepareTeacherDraft();ui.step=1;navigate('new');}
    if(a==='all-requests')navigate('requests');
    if(a==='filter'){ui.filter=el.dataset.filter;render();}
    if(a==='detail'){ui.requestId=el.dataset.id;navigate('detail');}
    if(a==='back-list')navigate('requests');
    if(a==='review-suppliers')navigate('suppliers');
    if(a==='previous-step'){captureDraft($('#request-form'));ui.step--;render();}
    if(a==='send-otp'){captureDraft($('#request-form'));toast('演示驗證碼為 123456，未發送真實短信。');}
    if(a==='remove-file'){captureDraft($('#request-form'));draft.files.splice(Number(el.dataset.index),1);saveDraft();render();}
    if(a==='accept')showWorkflowForm('accept-invitation',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='withdraw')showWorkflowForm('withdraw',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='quote-form')showQuoteForm(el.dataset.id);
    if(a==='try-supplier')switchRole('supplier');
    if(a==='supplier-messages'){const r=state.requests.find(r=>r.id===el.dataset.id);modal('需求問答',messagesPanel(r,'supplier'));}
    if(a==='toggle-shortlist'){window.IQ.toggleShortlist(state,el.dataset.id,el.dataset.quote);render();toast('洽談名單已更新；此操作並非確認成交。');}
    if(a==='review-quote')showWorkflowForm('review',state.requests.find(r=>r.id===el.dataset.id),el.dataset.quote);
    if(a==='deliver-stage')showWorkflowForm('deliver',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='next-stage')showWorkflowForm('next',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='edit-request')showWorkflowForm('edit',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='teacher-decision')showWorkflowForm(el.dataset.decision,state.requests.find(r=>r.id===el.dataset.id));
    if(a==='approve'){window.IQ.approveSupplier(state,el.dataset.id,true);render();toast('供應商已獲批准。');}
    if(a==='suspend'){modal('暫停此供應商接單？','<p>停權後，這間公司將不再收到新的報價邀請。已有報價保留。</p>',btn('取消','close-modal','secondary')+btn('確認停權','confirm-suspend','danger','',`data-id="${el.dataset.id}"`));}
    if(a==='confirm-suspend'){window.IQ.approveSupplier(state,el.dataset.id,false);closeModal();render();toast('已暫停該供應商接單。');}
    if(a==='dispatch'){const n=window.IQ.dispatch(state,el.dataset.id);render();toast(n?`已補派 ${n} 間合資格供應商，演示通知已加入佇列。`:'目前沒有可補派的新供應商；請查看下一階段或調整安排。');}
    if(a==='close-request')showWorkflowForm('close',state.requests.find(r=>r.id===el.dataset.id));
    if(a==='close-modal'){closeModal();render();}
    if(a==='reset'){modal('重置演示數據？','<p>當前瀏覽器中新增的需求、報價及修改會被清除，並恢復初始示例。</p>',btn('保留數據','close-modal','secondary')+btn('確認重置','confirm-reset','danger'));}
    if(a==='confirm-reset'){state=window.IQ.reset();window.IQAccess.ensure(state);session={accounts:{},revisions:{},signedOut:false};initializeSession();saveSession();draft={title:'',category:'到校課程',district:'九龍城區',description:'',budget:'',deadlineHours:72,school:'',teacher:'',phone:'',email:'',files:[],verified:false};localStorage.removeItem('instiquote-draft');closeModal();navigate(roleHome());toast('已恢復初始演示數據。');}
    if(a==='export'){const rows=[['訂單編號','需求','類別','地區','狀態','接單數','有效報價數','老師收集截止時間'],...state.requests.map(r=>[r.id,r.title,r.category,r.district,statuses[r.status]?.[0]||r.status,countAccepted(r),validQuotes(r).length,r.deadline])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='InstiQuote-需求報表.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('報表已導出。');}
  });});
  document.addEventListener('input',e=>{if(accountView.handleInput(e))return;if(waView.handleInput(e))return;if(e.target.id==='request-search'){ui.search=e.target.value;$('#request-list').innerHTML=requestCards();}if(e.target.closest('#request-form'))captureDraft($('#request-form'));});
  document.addEventListener('change',e=>{if(e.target.id==='session-account'){syncExternalState();const selected=state.access.accounts.find(a=>a.id===e.target.value&&a.type===ui.role);if(!selected)return;session.accounts[ui.role]=selected.id;session.revisions[selected.id]=selected.loginRevision;session.signedOut=false;selected.lastLoginAt=selected.status==='active'?new Date().toISOString():selected.lastLoginAt;if(selected.status==='active')window.IQAccess.record(state,selected.id,'session_switched',selected.id,'切換演示帳號');window.IQ.save(state);saveSession();closeModal();navigate(roleHome());return;}if(accountView.handleChange(e))return;if(waView.handleChange(e))return;if(e.target.name==='deadlineHours'){$$('.radio-card').forEach(x=>x.classList.toggle('selected',x.contains(e.target)));}if(e.target.id==='attachment-input'){safe(()=>{captureDraft($('#request-form'));const files=Array.from(e.target.files);if(files.some(f=>f.size>10*1024*1024))throw new Error('每份附件請控制在 10 MB 以內。');draft.files.push(...files.map(f=>({name:f.name,size:f.size,type:f.type})));saveDraft();render();});}});
  const $$=s=>Array.from(document.querySelectorAll(s));
  document.addEventListener('submit',e=>{if(['access-account-form','access-permissions-form'].includes(e.target.id)){e.preventDefault();safe(()=>{syncExternalState();requireActive();accountView.handleSubmit(e.target);});return;}if(e.target.id==='wa-compose-form'){e.preventDefault();safe(()=>{syncExternalState();requirePermission('whatsapp.send');waView.handleSubmit(e.target);});return;}if(e.target.id==='workflow-form'){e.preventDefault();safe(()=>{syncExternalState();requireActive();handleWorkflowSubmit(e.target);});return;}if(!['request-form','quote-form','message-form'].includes(e.target.id))return;e.preventDefault();safe(()=>{syncExternalState();const form=e.target,fd=new FormData(form);if(form.id==='request-form'){requireActive('teacher');captureDraft(form);if(ui.step===2){if(fd.get('otp')!=='123456')throw new Error('請輸入正確的演示驗證碼：123456。');if(!/^[+\d\s-]{8,16}$/.test(draft.phone))throw new Error('請填寫有效的演示聯繫電話。');draft.verified=true;saveDraft();}if(ui.step<3){ui.step++;render();window.scrollTo({top:0,behavior:'smooth'});}else{const r=window.IQ.createRequest(state,{...draft,deadlineHours:Number(draft.deadlineHours),budget:Number(draft.budget)||0});r.ownerAccountId=actor().id;window.IQ.save(state);queueNotification('request_received',r);localStorage.removeItem('instiquote-draft');localStorage.removeItem('instiquote-draft-'+actor().id);draft={title:'',category:'到校課程',district:'九龍城區',description:'',budget:'',deadlineHours:72,school:'',teacher:'',phone:'',email:'',files:[],verified:false};ui.requestId=r.id;ui.view='detail';render();toast('需求已發佈，已開始匹配供應商。');}}if(form.id==='quote-form'){requireSupplier();const existingRequest=state.requests.find(r=>r.id===form.dataset.request);if(Number(form.dataset.revision)!==existingRequest.revision)throw Error('需求已更新，請重新開啟報價表單。');const oldQuote=existingRequest.quotes.find(q=>q.supplierId===ui.supplierId);if(Number(form.dataset.quoteRevision)!==(oldQuote?.quoteRevision||0))throw Error('這份報價已有新的修訂，請重新開啟表單。');const file=fd.get('quoteAttachment');window.IQ.submitQuote(state,form.dataset.request,ui.supplierId,{amount:Number(fd.get('amount')),description:fd.get('description'),validDays:Number(fd.get('validDays')),attachmentName:file?.name||oldQuote?.attachmentName||''});const quoted=state.requests.find(r=>r.id===form.dataset.request);queueNotification('quote_received',quoted);closeModal();render();toast('報價已提交待審，符合要求後會按階段交付老師。');}if(form.id==='message-form'){if(isStaff())requirePermission('requests.manage');else if(ui.role==='teacher')requireOwnRequest(state.requests.find(r=>r.id===form.dataset.request));else{requireSupplier();if(!state.requests.find(r=>r.id===form.dataset.request)?.invitations.some(i=>i.supplierId===ui.supplierId))throw Error('未獲邀的需求不能留言。');}window.IQ.addMessage(state,form.dataset.request,form.dataset.author,fd.get('message'));const inModal=!!form.closest('#modal-root');if(inModal){const r=state.requests.find(r=>r.id===form.dataset.request);modal('需求問答',messagesPanel(r,'supplier'));}else render();toast('留言已保存到平台。');}});});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){const hadModal=$('#modal-root').hasChildNodes();closeModal();if(ui.notifications||hadModal){ui.notifications=false;render();}}});
  window.addEventListener('storage',e=>{if(e.key===window.IQ.storageKey){try{syncExternalState();closeModal();render();}catch(error){toast(error.message);}}});
  render();
  setInterval(()=>{safe(()=>{const changed=syncExternalState();if((synchronizeDeadlines()||changed)&&ui.view!=='new'&&!$('#modal-root').hasChildNodes())render();});},10000);
})();
